export function onOpen(ctx, {player, door}) {
  const p = ctx.resolve(player);
  const d = ctx.resolve(door);
  if ('some' in p && 'some' in d) {
    const pe = ctx.require(p);
    const de = ctx.require(d);
    const openCell = ctx.read(de, 'open');
    if ('some' in openCell) {
      const isOpen = ctx.require(openCell);
      if (!isOpen) {
        const keysCell = ctx.read(pe, 'keys');
        const keys = ctx.require(keysCell);
        if (keys >= 1) {
          ctx.write(pe, 'keys', ctx.sub(keys, 1));
          ctx.write(de, 'open', true);
          ctx.emit('Opened', {door: de});
        } else {
          ctx.emit('MissingKey', {player: pe});
        }
      }
    }
  }
}
